def tc(inp, out, label=''):
    return {'id': '', 'input': inp, 'expectedOutput': out, **({'label': label} if label else {})}

def task(id, title, ch, topics, difficulty, statement, input_format, output_format, constraints, tests, reference, hints=None, explanation=None):
    tests = [tc(i, o, label) if len(item) == 3 else tc(i, o) for item in tests for i, o, *label in [item]]
    for index, test in enumerate(tests, 1): test['id'] = f'case-{index}'
    hints = hints or [f'先明确输入中的数据和需要输出的结果，再选择 {topics[0]} 相关语法。', '把程序拆成读取、处理、输出三个阶段，先用最小样例手动跟踪变量变化。', '完成后检查边界值、循环条件和输出换行，确认每个测试都使用了真实输入。']
    examples = [{'input': tests[0]['input'], 'output': tests[0]['expectedOutput'].rstrip('\n')}, {'input': tests[1]['input'], 'output': tests[1]['expectedOutput'].rstrip('\n')}] if len(tests) > 1 else [{'input': tests[0]['input'], 'output': tests[0]['expectedOutput'].rstrip('\n')}]
    return {
        'source': 'C·Path Originals / 原创基础练习', 'sourceKind': 'original', 'reviewStatus': 'reviewed',
        'contentStatus': 'ready-for-local-judge', 'testVersion': 'originals-v2', 'author': 'C·Path maintainers',
        'constraints': constraints, 'id': id, 'title': title, 'chapter': ch, 'topics': topics,
        'difficulty': difficulty, 'statement': statement, 'inputFormat': input_format,
        'outputFormat': output_format, 'examples': examples, 'hints': hints,
        'explanation': explanation or f'这道题通过{topics[0]}练习把输入、处理和输出串起来，适合在完成前置知识后独立实现。',
        'starterCode': '#include <stdio.h>\n\nint main(void) {\n    return 0;\n}\n',
        'referenceSolution': reference, 'testCases': tests,
        'provenance': {'path': 'src/data/originals-phase6.json', 'sha256': 'generated-from-reviewed-original', 'readmeScore': '', 'contentStatus': 'C·Path authored content'},
    }

